def transform(grid):
    g = np.array(grid)
    bg = background(g)
    vals, counts = np.unique(g, return_counts=True)
    # seed: colour occurring exactly once, not the background
    seed_col = None
    for v, c in zip(vals, counts):
        if c == 1 and v != bg:
            seed_col = int(v)
    sy, sx = map(int, np.argwhere(g == seed_col)[0])
    out = g.copy()
    H, W = g.shape
    for y in range(sy % 2, H, 2):
        changed = False
        for x in range(sx % 2, W, 2):
            if out[y, x] == bg:
                out[y, x] = seed_col
                changed = True
        if changed:
            emit(out, f"Row {y}: every background cell at a column with the seed's parity (x%2=={sx%2}) gets the seed colour {seed_col}.")
    emit(out, "Final: the seed's parity lattice is filled wherever the background shows through.")
    return out
